-- vw_reporte_gestiones_expertis_v2
CREATE ALGORITHM=UNDEFINED SQL SECURITY DEFINER VIEW `vw_reporte_gestiones_expertis_v2` AS with GESTIONES_NORMALIZADAS as (select `g`.`id` AS `id`,`g`.`fecha_gestion` AS `fecha_gestion`,`g`.`dni` AS `dni`,`g`.`telefono` AS `telefono`,`g`.`status` AS `status`,ucase(trim(`g`.`tipificacion`)) AS `tipificacion`,`g`.`observacion` AS `observacion`,`g`.`fecha_pago` AS `fecha_pago`,`g`.`monto_pago` AS `monto_pago`,`g`.`nombre` AS `nombre`,case when char_length(trim(cast(`g`.`dni` as char charset utf8mb4))) < 8 then lpad(trim(cast(`g`.`dni` as char charset utf8mb4)),8,'0') else trim(cast(`g`.`dni` as char charset utf8mb4)) end collate utf8mb4_unicode_ci AS `dni_normalizado` from `gestiones` `g` where ucase(trim(`g`.`tipificacion`)) in ('PPC','PPM','PAR','RPP','CAN','VLL','TAT','REN','REC','FAL','MCT','DES','GRB','HOM','ILC','NOC','NTT'))select `g`.`id` AS `ID Gestion`,'ESCALL' AS `Canal Gestion`,coalesce(`a`.`canal`,'ESCALL') AS `Canal Asignacion`,`g`.`dni_normalizado` AS `DNI`,`a`.`titular` AS `Nombre Cliente`,`a`.`cartera` AS `Cartera`,ucase(`g`.`nombre`) AS `Asesor`,'KATHERINE HUAMAN' AS `Equipo`,`g`.`telefono` AS `Telefono`,`g`.`fecha_gestion` AS `Fecha Llamada`,`a`.`cosecha` AS `Cosecha`,case when `g`.`observacion` regexp '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}' then substr(`g`.`observacion`,12,8) when `g`.`observacion` regexp '^[0-9]{2}:[0-9]{2}:[0-9]{2}' then left(`g`.`observacion`,8) else NULL end AS `Hora`,`g`.`status` AS `Nivel 1`,`g`.`tipificacion` AS `Nivel 2`,`g`.`fecha_pago` AS `Fecha Compromiso`,coalesce(`g`.`monto_pago`,0) AS `Monto`,case when `g`.`observacion` regexp '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}' then trim(substr(`g`.`observacion`,20)) when `g`.`observacion` regexp '^[0-9]{2}:[0-9]{2}:[0-9]{2}' then trim(substr(`g`.`observacion`,9)) else `g`.`observacion` end AS `Observacion`,'MANUAL' AS `Medio Gestion`,coalesce(`a`.`cantidad_cuentas`,0) AS `Cantidad Cuentas`,`a`.`cuentas` AS `Cuentas`,`a`.`carteras` AS `Carteras`,`a`.`cosechas` AS `Cosechas`,case when `a`.`documento` is null then 0 else 1 end AS `Tiene Asignacion` from (`GESTIONES_NORMALIZADAS` `g` left join `vw_expertis_asignacion_dni` `a` on(`a`.`documento` collate utf8mb4_unicode_ci = `g`.`dni_normalizado` collate utf8mb4_unicode_ci and `a`.`periodo` = date_format(`g`.`fecha_gestion`,'%Y%m')));

