rtis_Historico`.`fechaCastigo` AS `fecha_castigo`,`Asignacion_Expertis_Historico`.`C1` AS `c1`,`Asignacion_Expertis_Historico`.`C2` AS `c2`,`Asignacion_Expertis_Historico`.`C3` AS `c3`,`Asignacion_Expertis_Historico`.`C6` AS `c6`,`Asignacion_Expertis_Historico`.`C12` AS `c12`,`Asignacion_Expertis_Historico`.`C24` AS `c24`,`Asignacion_Expertis_Historico`.`nvl_Asesor` AS `nvl_asesor` from `Asignacion_Expertis_Historico` where `Asignacion_Expertis_Historico`.`FEC_PRO` is not null;

